@startuml behavioral
' Swimlanes
|Customer|
start
:Submit Order;
if (Order valid?) then (yes)
  :Order [submitted];
else (no)
  stop
endif
|OrderStaff|
:Receive Order;
if (status == submitted) then (yes)
  :Order [pending];
else (no)
  stop
endif
:Fill Order;
if (status == pending) then (yes)
  :Order [filled];
else (no)
  stop
endif
fork
  :Ship Order;
  if (status == filled) then (yes)
    :Order [shipped];
  else (no)
    stop
  endif
fork again
  :Raise Invoice;
  if (status == filled or shipped) then (yes)
    :Invoice [issued];
  else (no)
    stop
  endif
join
|Customer|
:Submit Payment;
if (Invoice status == issued) then (yes)
  :Payment [pending];
else (no)
  stop
endif
|Accountant|
:Confirm Payment;
if (Payment status == pending) then (yes)
  :Payment [completed];
  :Invoice [paid];
else (no)
  stop
endif
|OrderStaff|
:Close Order;
if (status == shipped and Invoice status == paid) then (yes)
  :Order [closed];
else (no)
  stop
endif
stop
@enduml

