{
  "version": "1.1",
  "updated": "2026-10-21",
  "requirements": [
    {
      "id": "US-01",
      "type": "functional",
      "statement": "As a Customer, I want to submit an order that references existing products and a payment method, so that I can purchase items.",
      "acceptance_criteria": [
        {"id": "US-01-AC01", "format": "given_when_then", "text": "Given the customer is known, the order contains at least one order item, and each order item refers to an existing product, When the customer submits the order, Then the system creates an Order with status submitted, sets the order date to the submission date, and calculates the total amount as the sum of (quantity × unit price) for all items."},
        {"id": "US-01-AC02", "format": "condition", "text": "All mandatory customer attributes (name, address, phone number) must be present; the optional bank account may be absent."},
        {"id": "US-01-AC03", "format": "given_when_then", "text": "Given the order fails any validation (unknown customer, no items, or non‑existent product), When the customer attempts to submit, Then the system rejects the submission and no Order record is created."}
      ]
    },
    {
      "id": "US-02",
      "type": "functional",
      "statement": "As a Customer, I want my personal data (name, address, phone, optional bank account) stored securely, so that my information is protected.",
      "acceptance_criteria": [
        {"id": "US-02-AC01", "format": "condition", "text": "The system stores a name, address and phone number for each Customer; the bank account is optional and stored only if provided."},
        {"id": "US-02-AC02", "format": "condition", "text": "All attributes are mandatory except the bank account; attempts to create a Customer without a mandatory attribute are rejected."},
        {"id": "US-02-AC03", "format": "given_when_then", "text": "Given a request to create a Customer, When the request includes all mandatory fields, Then the system persists the Customer record and encrypts the bank account data at rest and in transit."}
      ]
    },
    {
      "id": "US-03",
      "type": "functional",
      "statement": "As an OrderStaff, I want to receive a submitted order, so that it can be processed.",
      "acceptance_criteria": [
        {"id": "US-03-AC01", "format": "given_when_then", "text": "Given an Order whose status is submitted, When OrderStaff invokes receive order, Then the Order status changes to pending."},
        {"id": "US-03-AC02", "format": "condition", "text": "The status transition submitted → pending is the only allowed change for this action."},
        {"id": "US-03-AC03", "format": "given_when_then", "text": "Given an Order whose status is not submitted, When OrderStaff attempts to receive it, Then the system rejects the request and the status remains unchanged."}
      ]
    },
    {
      "id": "US-04",
      "type": "functional",
      "statement": "As an OrderStaff, I want to mark a pending order as filled, so that it can be shipped.",
      "acceptance_criteria": [
        {"id": "US-04-AC01", "format": "given_when_then", "text": "Given an Order with status pending, When OrderStaff marks it as filled, Then the status becomes filled."},
        {"id": "US-04-AC02", "format": "condition", "text": "The only permitted transition for this action is pending → filled."},
        {"id": "US-04-AC03", "format": "given_when_then", "text": "Given an Order whose status is not pending, When OrderStaff attempts to fill it, Then the request is rejected and the status stays unchanged."}
      ]
    },
    {
      "id": "US-05",
      "type": "functional",
      "statement": "As an OrderStaff, I want to decline a pending order, so that it is closed without further processing.",
      "acceptance_criteria": [
        {"id": "US-05-AC01", "format": "given_when_then", "text": "Given an Order with status pending, When OrderStaff declines it, Then the status changes to closed."},
        {"id": "US-05-AC02", "format": "condition", "text": "The transition pending → closed is allowed only for decline actions."},
        {"id": "US-05-AC03", "format": "given_when_then", "text": "Given an Order whose status is not pending, When OrderStaff attempts to decline, Then the request is rejected and the status remains unchanged."}
      ]
    },
    {
      "id": "US-06",
      "type": "functional",
      "statement": "As an OrderStaff, I want to ship a filled order, so that the customer receives the goods.",
      "acceptance_criteria": [
        {"id": "US-06-AC01", "format": "given_when_then", "text": "Given an Order with status filled, When OrderStaff ships it, Then the status becomes shipped."},
        {"id": "US-06-AC02", "format": "condition", "text": "The only permitted transition for shipping is filled → shipped."},
        {"id": "US-06-AC03", "format": "given_when_then", "text": "Given an Order whose status is not filled, When OrderStaff attempts to ship, Then the request is rejected and the status stays unchanged."}
      ]
    },
    {
      "id": "US-07",
      "type": "functional",
      "statement": "As an OrderStaff, I want to close a shipped order whose invoice is paid, so that the order lifecycle ends.",
      "acceptance_criteria": [
        {"id": "US-07-AC01", "format": "given_when_then", "text": "Given an Order with status shipped and an associated Invoice with status paid, When OrderStaff closes the order, Then the Order status becomes closed."},
        {"id": "US-07-AC02", "format": "given_when_then", "text": "Given a shipped Order whose Invoice is not paid, When OrderStaff attempts to close, Then the request is rejected and the status remains shipped."},
        {"id": "US-07-AC03", "format": "given_when_then", "text": "Given an Order whose status is not shipped, When OrderStaff attempts to close, Then the request is rejected."}
      ]
    },
    {
      "id": "US-08",
      "type": "functional",
      "statement": "As an Accountant, I want to raise an invoice for a filled or shipped order that has no invoice, so that the customer can be billed.",
      "acceptance_criteria": [
        {"id": "US-08-AC01", "format": "given_when_then", "text": "Given an Order with status filled or shipped and no existing Invoice, When Accountant creates an Invoice with date, amount, payment method, and status issued, Then the Invoice is linked to the Order."},
        {"id": "US-08-AC02", "format": "condition", "text": "An Order may have at most one Invoice; attempts to create a second Invoice are rejected."},
        {"id": "US-08-AC03", "format": "given_when_then", "text": "Given an Order whose status is submitted, pending or closed, When Accountant attempts to raise an Invoice, Then the request is rejected."}
      ]
    },
    {
      "id": "US-09",
      "type": "functional",
      "statement": "As a Customer, I want to submit a payment against an issued invoice, so that I can settle my bill.",
      "acceptance_criteria": [
        {"id": "US-09-AC01", "format": "given_when_then", "text": "Given an Invoice with status issued, When the Customer submits a Payment with date, amount and payment method, Then the system creates a Payment with status pending linked to the Invoice."},
        {"id": "US-09-AC02", "format": "given_when_then", "text": "Given an Invoice with status paid, When the Customer attempts to submit a Payment, Then the request is rejected."},
        {"id": "US-09-AC03", "format": "condition", "text": "Multiple Payments are allowed; each Payment is recorded separately and retains its own status."}
      ]
    },
    {
      "id": "US-10",
      "type": "functional",
      "statement": "As an Accountant, I want to confirm a pending payment, so that the invoice can be marked paid.",
      "acceptance_criteria": [
        {"id": "US-10-AC01", "format": "given_when_then", "text": "Given a Payment with status pending linked to an Invoice whose status is issued, When Accountant confirms the payment, Then the Payment status becomes completed and the Invoice status becomes paid."},
        {"id": "US-10-AC02", "format": "condition", "text": "The only allowed transition for a Payment is pending → completed (or failed)."},
        {"id": "US-10-AC03", "format": "given_when_then", "text": "Given a Payment whose status is not pending, When Accountant attempts to confirm, Then the request is rejected and the status remains unchanged."}
      ]
    },
    {
      "id": "US-11",
      "type": "functional",
      "statement": "As an Accountant, I want to reject a pending payment, so that the customer can retry.",
      "acceptance_criteria": [
        {"id": "US-11-AC01", "format": "given_when_then", "text": "Given a Payment with status pending, When Accountant rejects it, Then the Payment status becomes failed and the related Invoice and Order statuses stay unchanged."},
        {"id": "US-11-AC02", "format": "given_when_then", "text": "Given a Payment whose status is not pending, When Accountant attempts to reject, Then the request is rejected."},
        {"id": "US-11-AC03", "format": "condition", "text": "A failed Payment remains in the system; subsequent payments may be submitted."}
      ]
    },
    {
      "id": "US-12",
      "type": "functional",
      "statement": "As a system, I want to enforce allowed values for statuses, payment methods and monetary types, so that data integrity is maintained.",
      "acceptance_criteria": [
        {"id": "US-12-AC01", "format": "condition", "text": "Order status is restricted to submitted, pending, filled, shipped, closed."},
        {"id": "US-12-AC02", "format": "condition", "text": "Invoice status is restricted to issued or paid."},
        {"id": "US-12-AC03", "format": "condition", "text": "Payment status is restricted to pending, completed or failed."},
        {"id": "US-12-AC04", "format": "condition", "text": "Payment method is limited to bank, card or cash for Orders, Invoices and Payments."},
        {"id": "US-12-AC05", "format": "condition", "text": "All monetary attributes (price, unit price, totals, amounts) are stored as decimal numbers."}
      ]
    },
    {
      "id": "NFR-01",
      "type": "performance",
      "statement": "When a user submits an order containing up to 50 order items under normal operating conditions, the system shall register the order and respond within 2 seconds for at least 95% of submissions.",
      "acceptance_criteria": []
    },
    {
      "id": "NFR-02",
      "type": "performance",
      "statement": "Under normal operating conditions, the system shall support at least 200 concurrent users and at least 20 order submissions per second while meeting the response time of NFR-01.",
      "acceptance_criteria": []
    },
    {
      "id": "NFR-03",
      "type": "security",
      "statement": "The system shall authenticate every user before granting access to any customer, order, invoice or payment data, and shall reject 100% of unauthenticated requests.",
      "acceptance_criteria": []
    },
    {
      "id": "NFR-04",
      "type": "security",
      "statement": "The system shall allow only users holding the accountant role to confirm or reject a payment, and shall reject the same request from any other user.",
      "acceptance_criteria": []
    },
    {
      "id": "NFR-05",
      "type": "security",
      "statement": "The system shall protect customer personal data and bank account numbers by encrypting them in transit with TLS 1.2 or higher and at rest.",
      "acceptance_criteria": []
    },
    {
      "id": "NFR-06",
      "type": "availability",
      "statement": "The system shall be available for at least 99.5% of each calendar month, excluding scheduled maintenance announced at least 24 hours in advance.",
      "acceptance_criteria": []
    },
    {
      "id": "NFR-07",
      "type": "availability",
      "statement": "When a server failure occurs, the system shall resume accepting requests within 15 minutes without losing any order, invoice or payment recorded before the failure.",
      "acceptance_criteria": []
    },
    {
      "id": "NFR-08",
      "type": "availability",
      "statement": "The system shall record the user and the time of every status change of an order, an invoice and a payment, and shall retain these records for at least 12 months.",
      "acceptance_criteria": []
    }
  ]
}

