@startuml behavioral
|Customer|
start
:Submit Order;\n:Order [submitted];
if (Order valid?) then (yes)
  :Create Order;\n:Order [submitted];
else (no)
  stop
endif

|OrderStaff|
if (Order status == submitted) then (yes)
  :Receive Order;\n:Order [pending];
else (no)
  stop
endif
if (Order status == pending) then (yes)
  :Mark Filled;\n:Order [filled];
endif
if (Order status == pending) then (yes)
  :Decline Order;\n:Order [closed];
endif
if (Order status == filled) then (yes)
  :Ship Order;\n:Order [shipped];
endif
if (Order status == shipped && Invoice status == paid) then (yes)
  :Close Order;\n:Order [closed];
endif

|Accountant|
if (Order status == filled || Order status == shipped) then (yes)
  :Raise Invoice;\n:Invoice [issued];
endif
if (Invoice status == issued) then (yes)
  :Submit Payment;\n:Payment [pending];
endif
if (Payment status == pending) then (yes)
  :Confirm Payment;\n:Payment [completed];\n:Invoice [paid];
else (reject)
  :Reject Payment;\n:Payment [failed];
endif

stop
@enduml

