      "type": "functional",
      "statement": "As OrderStaff, I want to mark a pending order as filled, so that it is ready for shipping or invoicing.",
      "acceptance_criteria": [
        {"id": "US-05-AC01", "format": "given_when_then", "text": "Given an Order with status pending, When OrderStaff marks it as filled, Then the status becomes filled (REQ‑F‑20)."},
        {"id": "US-05-AC02", "format": "given_when_then", "text": "Given an Order whose status is not pending, When OrderStaff attempts to mark it filled, Then the status remains unchanged (REQ‑F‑21)."},
        {"id": "US-05-AC03", "format": "condition", "text": "Status transition pending → filled is permitted (REQ‑F‑49)."}
      ]
    },
    {
      "id": "US-06",
      "type": "functional",
      "statement": "As OrderStaff, I want to decline a pending order, so that it is closed without fulfillment.",
      "acceptance_criteria": [
        {"id": "US-06-AC01", "format": "given_when_then", "text": "Given an Order with status pending, When OrderStaff declines it, Then the status becomes closed (REQ‑F‑22)."},
        {"id": "US-06-AC02", "format": "given_when_then", "text": "Given an Order whose status is not pending, When OrderStaff attempts to decline, Then the status remains unchanged (REQ‑F‑23)."},
        {"id": "US-06-AC03", "format": "condition", "text": "Once an Order reaches closed, its status cannot change (REQ‑F‑44)."}
      ]
    },
    {
      "id": "US-07",
      "type": "functional",
      "statement": "As OrderStaff, I want to set a filled order to shipped, so that the customer receives the items.",
      "acceptance_criteria": [
