{"version":"1.1","updated":"2026-10-21","requirements":[
  {"id":"US-01","type":"functional","statement":"As a Customer, I want my personal details (name, address, phone) stored, so that the system can uniquely identify me.","acceptance_criteria":[
    {"id":"US-01-AC01","format":"condition","text":"Customer name, address and phone number are mandatory and stored as non-empty strings."},
