    {"id":"US-01-AC03","format":"given_when_then","text":"Given a valid customer input, When the customer is created, Then the record persists with the provided attributes."}
  ]},
  {"id":"US-02","type":"functional","statement":"As a Customer, I want to optionally add a single bank account, so that I can use it for payments.","acceptance_criteria":[
    {"id":"US-02-AC01","format":"condition","text":"A customer may have zero or one bank account; attempts to add a second bank account are rejected."},
    {"id":"US-02-AC02","format":"condition","text":"Bank account data is stored encrypted at rest and in transit."},
    {"id":"US-02-AC03","format":"given_when_then","text":"Given a customer without a bank account, When the customer adds a bank account, Then the account is linked to the customer."}
  ]},
  {"id":"US-03","type":"functional","statement":"As an OrderStaff, I want to maintain product information (name, description, price, image), so that customers can view accurate product data.","acceptance_criteria":[
