    {"id":"US-06-AC01","format":"given_when_then","text":"Given a filled or shipped order without an existing invoice, When the accountant raises an invoice, Then an invoice is created with status issued, the supplied date, amount, and payment method."},
    {"id":"US-06-AC02","format":"given_when_then","text":"Given an order that already has an invoice, When the accountant attempts to raise another invoice, Then the system rejects the request."},
    {"id":"US-06-AC03","format":"given_when_then","text":"Given an order with status submitted, pending or closed, When the accountant attempts to raise an invoice, Then the system rejects the request."},
    {"id":"US-06-AC04","format":"condition","text":"Payment method on an invoice is limited to bank, card, or cash."}
  ]},
  {"id":"US-07","type":"functional","statement":"As a Customer, I want to submit a payment against an issued invoice, so that I can settle my bill.","acceptance_criteria":[
    {"id":"US-07-AC01","format":"given_when_then","text":"Given an invoice with status issued, When the customer submits a payment with a valid payment method, Then a payment record is created with status pending."},
    {"id":"US-07-AC02","format":"given_when_then","text":"Given an invoice with status paid, When the customer attempts to submit a payment, Then the system rejects the request."},
    {"id":"US-07-AC03","format":"given_when_then","text":"Given an invoice whose previous payment has status failed, When the customer submits a new payment, Then the new payment is created with status pending and the failed payment remains failed."}
  ]},
  {"id":"US-08","type":"functional","statement":"As an Accountant, I want to confirm or reject a pending payment, so that the invoice status reflects the payment outcome.","acceptance_criteria":[
