    {"id":"US-09-AC03","format":"condition","text":"Once an order reaches status closed, no further status changes are allowed."}
  ]},
  {"id":"US-10","type":"functional","statement":"As the system, I want to enforce data‑integrity rules (mandatory attributes, multiplicities, decimal types, enumerated values), so that the data remains consistent.","acceptance_criteria":[
    {"id":"US-10-AC01","format":"condition","text":"All monetary values (product price, unit price, order total, invoice amount, payment amount) are stored as decimal numbers."},
    {"id":"US-10-AC02","format":"condition","text":"Order status is restricted to the enum values submitted, pending, filled, shipped, closed."},
    {"id":"US-10-AC03","format":"condition","text":"Invoice status is restricted to issued or paid."},
    {"id":"US-10-AC04","format":"condition","text":"Payment status is restricted to pending, completed, or failed."},
    {"id":"US-10-AC05","format":"condition","text":"Payment method on orders, invoices and payments is limited to bank, card, or cash."}
  ]},
  {"id":"NFR-01","type":"performance","statement":"When a user submits an order containing up to 50 order items under normal operating conditions, the system shall register the order and respond within 2 seconds for at least 95% of submissions.","acceptance_criteria":[]},
  {"id":"NFR-02","type":"performance","statement":"Under normal operating conditions, the system shall support at least 200 concurrent users and at least 20 order submissions per second while meeting the response time of NFR‑01.","acceptance_criteria":[]},
