  {"id":"NFR-05","type":"security","statement":"The system shall protect customer personal data and bank account numbers by encrypting them in transit with TLS 1.2 or higher and at rest.","acceptance_criteria":[]},
  {"id":"NFR-06","type":"security","statement":"The system shall record the user and the time of every status change of an order, an invoice and a payment, and shall retain these records for at least 12 months.","acceptance_criteria":[]},
  {"id":"NFR-07","type":"availability","statement":"The system shall be available for at least 99.5% of each calendar month, excluding scheduled maintenance announced at least 24 hours in advance.","acceptance_criteria":[]},
  {"id":"NFR-08","type":"availability","statement":"When a server failure occurs, the system shall resume accepting requests within 15 minutes without losing any order, invoice or payment recorded before the failure.","acceptance_criteria":[]}
]}

