{"content":"@startuml structural

' Enumerations
enum OrderStatus {
    submitted
    pending
    filled
    shipped
    closed
}

enum InvoiceStatus {
    issued
    paid
}

enum PaymentStatus {
    pending
    completed
    failed
}

enum PaymentMethod {
    bank
    card
    cash
}

' Domain classes
class Customer {
    +String name
    +String address
    +String phoneNumber
    +BankAccount? bankAccount
}

class BankAccount {
    +String accountNumber
    +String bankName
    +String routingNumber
}

class Product {
    +String name
    +String description
    +Decimal price
    +String imageUrl
}

class Order {
    +Date orderDate
    +Decimal totalAmount
    +OrderStatus status
    +PaymentMethod paymentMethod
}

class OrderItem {
    +int quantity
    +Decimal unitPrice
}

class Invoice {
    +Date date
    +Decimal amount
    +InvoiceStatus status
    +PaymentMethod paymentMethod
}

class Payment {
    +Date date
    +Decimal amount
    +PaymentStatus status
    +PaymentMethod paymentMethod
}

' Relationships
Customer "1" -- "*" Order : places >
Order "1" -- "*" OrderItem : contains >
OrderItem "*" -- "1" Product : refers to >
Order "1" -- "0..1" Invoice : has >
Invoice "1" -- "*" Payment : records >

@enduml","encoding":"utf-8","mode":"overwrite","path":"structural.puml"}

{"content":"@startuml behavioral
skinparam participantMargin 20

|Customer|
start
:SubmitOrder;
if (order valid?) then (yes)
  :CreateOrder [submitted];
else (no)
  stop
endif

|OrderStaff|
if (order status == submitted) then (receive)
  :ReceiveOrder;
  :SetOrderStatus [pending];
else (reject)
  note right: REJECT if not submitted
endif

if (order status == pending) then (fill)
  :MarkFilled;
  :SetOrderStatus [filled];
else (reject)
  note right: REJECT if not pending
endif

if (order status == filled) then (ship)
  :ShipOrder;
  :SetOrderStatus [shipped];
else (reject)
  note right: REJECT if not filled
endif

if (order status == shipped && invoice status == paid) then (close)
  :CloseOrder;
  :SetOrderStatus [closed];
else (reject)
  note right: REJECT if conditions not met
endif

|Accountant|
if (order status in {filled, shipped} && no invoice) then (raise invoice)
  :RaiseInvoice;
  :CreateInvoice [issued];
else (reject)
  note right: REJECT per rules
endif

if (invoice status == issued) then (submit payment)
  :SubmitPayment;
  :CreatePayment [pending];
else (reject)
  note right: REJECT if invoice paid
endif

if (payment status == pending) then (confirm payment)
  :ConfirmPayment;
  :SetPaymentStatus [completed];
  :SetInvoiceStatus [paid];
else (reject)
  note right: REJECT if not pending
endif

if (payment status == pending) then (reject payment)
  :RejectPayment;
  :SetPaymentStatus [failed];
else (reject)
  note right: REJECT if not pending
endif

stop
@enduml","encoding":"utf-8","mode":"overwrite","path":"behavioral.puml"}

